/* Level overlay code; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"
#include "rnc/math/asm_helpers.h"

typedef struct {
    s32 a;
    s16 h;
} K0024ed18;

typedef struct {
    u8         pad[0x10];
    u8         n;
    u8         pad2[0xB];
    K0024ed18 *k[1];
} O0024ed18;

s32 find_nearest_animation_sequence_entry(O0024ed18 *animation_sequence,
                                          f32 target_sequence_position) __asm__("FUN_L00_0024ed18");

s32 find_nearest_animation_sequence_entry(O0024ed18 *animation_sequence,

                                          f32 target_sequence_position) {
    s16 scaled_target_position = truncate_float_to_s32(target_sequence_position * 16.0f);
    s32 i;
    for (i = 0; i < animation_sequence->n; i++) {
        if (scaled_target_position < animation_sequence->k[i]->h) {
            if (i > 0) {
                if (scaled_target_position - animation_sequence->k[i - 1]->h <
                    animation_sequence->k[i]->h - scaled_target_position)
                    i = i - 1;
            }
            return i;
        }
    }
    return -1;
}
